/// A shadcn/ui style translated into preset values (px, opacity 0–1).
///
/// The 8 styles of the new system (Vega, Nova, Maia, Lyra, Mira, Luma, Rhea,
/// Sera) are generated by tool/gen_shadcn_styles.py into `shadcn_styles.dart`;
/// [ShadcnStyleSpec.newYork] is the classic new-york-v4 style.
///
/// Colors are token references as in CSS: "muted", "input/30",
/// "transparent" (see `shadcnRef` in the preset).
class ShadcnStyleSpec {
  const ShadcnStyleSpec({
    required this.name,
    required this.font,
    required this.buttonRadius,
    required this.buttonFontSize,
    required this.buttonLineHeight,
    required this.buttonWeight,
    required this.buttonTracking,
    required this.buttonUppercase,
    required this.pressDown,
    required this.ringWidth,
    required this.ringAlpha,
    required this.sizes,
    required this.outlineShadow,
    required this.destructiveSoft,
    required this.primaryHoverAlpha,
    required this.secondaryHoverMix,
    required this.menuRing,
    required this.outlineBg,
    required this.outlineBgDark,
    required this.outlineHover,
    required this.outlineHoverDark,
    required this.ghostHover,
    required this.ghostHoverDark,
    required this.outlineDarkTransparent,
    required this.inputHeight,
    required this.inputRadius,
    required this.inputPaddingH,
    required this.inputFontSize,
    required this.inputLineHeight,
    required this.inputFillAlpha,
    required this.inputUnderline,
    required this.inputShadow,
    required this.inputRingWidth,
    required this.inputRingAlpha,
    required this.cardRadius,
    required this.cardRing,
    required this.cardShadow,
    required this.cardPadding,
    required this.dialogRadius,
    required this.dialogPadding,
    required this.dialogShadow,
    required this.dialogRing,
    required this.menuRadius,
    required this.menuPadding,
    required this.menuShadow,
    required this.itemRadius,
    required this.itemPaddingH,
    required this.itemPaddingV,
    required this.itemFontSize,
    required this.itemWeight,
    required this.tooltipRadius,
    required this.badgeRadius,
    required this.toastRadius,
    required this.toggleRadius,
    required this.toggleHeight,
    required this.togglePaddingH,
    required this.toggleFontSize,
    required this.checkboxRadius,
    required this.checkboxFillAlpha,
    required this.switchWidth,
    required this.switchHeight,
    required this.switchThumbWidth,
    required this.switchThumbHeight,
    required this.switchBorder,
    required this.sliderTrack,
    required this.sliderTrackFillAlpha,
    required this.sliderThumbWidth,
    required this.sliderThumbHeight,
    required this.sliderThumbRadius,
    required this.sliderThumbBorder,
    required this.sliderThumbFill,
    required this.sliderThumbShadow,
    required this.tabsFontSize,
  });

  final String name;
  final String font;

  // Buttons
  final double buttonRadius;
  final double buttonFontSize;
  final double buttonLineHeight;
  final int buttonWeight;

  /// letter-spacing in em (tracking-widest = 0,1).
  final double buttonTracking;

  /// Uppercase labels (Sera): Flutter can't do it from the theme.
  final bool buttonUppercase;

  /// `active:translate-y-px`: the button moves down 1px when pressed.
  final bool pressDown;
  final double ringWidth;
  final double ringAlpha;

  /// Size → (height, horizontal padding, (text, line height), radius).
  final Map<String, (double?, double, (double, double), double?)> sizes;
  final bool outlineShadow;
  final bool destructiveSoft;
  final double primaryHoverAlpha;
  final bool secondaryHoverMix;
  final (double, double)? menuRing;
  final String? outlineBg;
  final String? outlineBgDark;
  final String? outlineHover;
  final String? outlineHoverDark;
  final String? ghostHover;
  final String? ghostHoverDark;
  final bool outlineDarkTransparent;

  // Fields
  final double inputHeight;
  final double inputRadius;
  final double inputPaddingH;
  final double inputFontSize;
  final double inputLineHeight;
  final double inputFillAlpha;
  final bool inputUnderline;
  final bool inputShadow;
  final double inputRingWidth;
  final double inputRingAlpha;

  // Containers: ring = (light, dark opacity) of ring-1 ring-foreground/NN
  // instead of the border; null = `border` border.
  final double cardRadius;
  final (double, double)? cardRing;
  final String cardShadow;
  final double cardPadding;
  final double dialogRadius;
  final double dialogPadding;
  final String dialogShadow;
  final (double, double)? dialogRing;
  final double menuRadius;
  final double menuPadding;
  final String menuShadow;
  final double itemRadius;
  final double itemPaddingH;
  final double itemPaddingV;
  final double itemFontSize;
  final int itemWeight;
  final double tooltipRadius;
  final double badgeRadius;
  final double toastRadius;

  // Controlli
  final double toggleRadius;
  final double toggleHeight;
  final double togglePaddingH;
  final double toggleFontSize;
  final double checkboxRadius;
  final double checkboxFillAlpha;
  final double? switchWidth;
  final double? switchHeight;
  final double? switchThumbWidth;
  final double? switchThumbHeight;
  final double switchBorder;
  final double sliderTrack;
  final double sliderTrackFillAlpha;
  final double? sliderThumbWidth;
  final double? sliderThumbHeight;
  final double sliderThumbRadius;

  /// "primary", "ring" o "none".
  final String sliderThumbBorder;

  /// "white" o "primary".
  final String sliderThumbFill;
  final String sliderThumbShadow;
  final double tabsFontSize;

  /// new-york-v4, the classic style (registry/new-york-v4/ui).
  static const newYork = ShadcnStyleSpec(
    name: 'new-york',
    font: 'Geist',
    buttonRadius: 8,
    buttonFontSize: 14,
    buttonLineHeight: 20,
    buttonWeight: 500,
    buttonTracking: 0,
    buttonUppercase: false,
    pressDown: false,
    ringWidth: 3,
    ringAlpha: 0.5,
    sizes: {
      'default': (36, 16, (14, 20), 8),
      'xs': (24, 8, (12, 16), 8),
      'sm': (32, 12, (14, 20), 8),
      'lg': (40, 24, (14, 20), 8),
      'icon': (36, 0, (14, 20), 8),
    },
    outlineShadow: true,
    destructiveSoft: false,
    primaryHoverAlpha: 0.9,
    secondaryHoverMix: false,
    menuRing: null,
    outlineBg: 'background',
    outlineBgDark: 'input/30',
    outlineHover: 'accent',
    outlineHoverDark: 'input/50',
    ghostHover: 'accent',
    ghostHoverDark: 'accent/50',
    outlineDarkTransparent: false,
    inputHeight: 36,
    inputRadius: 8,
    inputPaddingH: 12,
    inputFontSize: 14,
    inputLineHeight: 20,
    inputFillAlpha: 0,
    inputUnderline: false,
    inputShadow: true,
    inputRingWidth: 3,
    inputRingAlpha: 0.5,
    cardRadius: 14,
    cardRing: null,
    cardShadow: 'sm',
    cardPadding: 24,
    dialogRadius: 10,
    dialogPadding: 24,
    dialogShadow: 'lg',
    dialogRing: null,
    menuRadius: 8,
    menuPadding: 4,
    menuShadow: 'md',
    itemRadius: 6,
    itemPaddingH: 8,
    itemPaddingV: 6,
    itemFontSize: 14,
    itemWeight: 400,
    tooltipRadius: 8,
    badgeRadius: 9999,
    toastRadius: 10,
    toggleRadius: 8,
    toggleHeight: 30,
    togglePaddingH: 10,
    toggleFontSize: 14,
    checkboxRadius: 4,
    checkboxFillAlpha: 0,
    switchWidth: 32,
    switchHeight: 18.4,
    switchThumbWidth: 16,
    switchThumbHeight: 16,
    switchBorder: 1,
    sliderTrack: 6,
    sliderTrackFillAlpha: 0,
    sliderThumbWidth: 16,
    sliderThumbHeight: 16,
    sliderThumbRadius: 9999,
    sliderThumbBorder: 'primary',
    sliderThumbFill: 'white',
    sliderThumbShadow: 'sm',
    tabsFontSize: 14,
  );
}
